-- Run only after this application release is verified on Hostinger production.
-- Activates the quotation-only catalogue; no price, stock or electrical certification is invented.
BEGIN;
UPDATE public.components SET is_active=TRUE WHERE visual_settings->>'asset_pack'='components-v1';
UPDATE public.enclosures SET is_active=TRUE WHERE visual_settings->>'asset_pack'='components-v1';
UPDATE public.configurator_templates SET preview_settings=COALESCE(preview_settings,'{}'::jsonb)||'{"asset_pack":"components-v1","commerce_mode":"quote","layout":"locked-1in1out"}'::jsonb,is_active=TRUE WHERE id IN ('c0c98f0c-807c-4767-aa60-857df285d183','a4501a4c-2d2f-4c09-8ba9-28978a85a054');
COMMIT;
